package pe.nexo.store.product;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;@Service public class ProductService{private final ProductRepository repository;public ProductService(ProductRepository r){repository=r;}public List<Product>findAll(String c){return c==null||c.isBlank()?repository.findAll():repository.findByCategoryIgnoreCase(c);}public List<Product>findOffers(){return repository.findByOriginalPriceIsNotNull().stream().filter(p->p.getOriginalPrice().compareTo(p.getPrice())>0).toList();}public Product findById(Long id){return repository.findById(id).orElseThrow(()->new ProductNotFoundException(id));}public Product findForOrder(Long id){return repository.findByIdForUpdate(id).orElseThrow(()->new ProductNotFoundException(id));}private void unique(ProductInput i,Long id){if(repository.existsBySkuIgnoreCaseAndIdNot(i.sku(),id==null?-1L:id))throw new IllegalStateException("El SKU ya existe");}@Transactional public Product create(ProductInput i){unique(i,null);return repository.save(new Product(null,i.sku(),i.name(),i.category(),i.price(),i.originalPrice(),i.rating(),i.image(),i.tag(),i.spec(),i.specifications(),i.stock(),i.inStock()));}@Transactional public Product update(Long id,ProductInput i){unique(i,id);Product p=findById(id);p.update(i.sku(),i.name(),i.category(),i.price(),i.originalPrice(),i.rating(),i.image(),i.tag(),i.spec(),i.specifications(),i.stock(),i.inStock());return p;}@Transactional public void delete(Long id){if(!repository.existsById(id))throw new ProductNotFoundException(id);repository.deleteById(id);}}
